sys_script_include.script:
var XurrentHMACUtil = Class.create();
XurrentHMACUtil.prototype = {
    initialize: function() {},

    generateHMAC: function(key, message) {
        return 'sha256=' + this._hmacSHA256(key, message);
    },

    _hmacSHA256: function(key, message) {
        var K = [
            0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
            0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
            0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
            0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
            0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
            0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
            0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
            0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
        ];

        function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }
        function add(a, b)  { return (a + b) | 0; }

        function sha256(bytes) {
            var H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
            var orig = bytes.length;
            bytes.push(0x80);
            while (bytes.length % 64 !== 56) bytes.push(0);
            var bl = orig * 8;
            bytes.push(0); bytes.push(0); bytes.push(0); bytes.push(0);
            bytes.push((bl >>> 24) & 0xff); bytes.push((bl >>> 16) & 0xff);
            bytes.push((bl >>> 8)  & 0xff); bytes.push(bl & 0xff);

            for (var i = 0; i < bytes.length; i += 64) {
                var W = [];
                for (var t = 0; t < 16; t++) {
                    W[t] = (bytes[i+t*4] << 24) | (bytes[i+t*4+1] << 16) |
                            (bytes[i+t*4+2] << 8) | bytes[i+t*4+3];
                }
                for (var t = 16; t < 64; t++) {
                    var s0 = rotr(W[t-15],7) ^ rotr(W[t-15],18) ^ (W[t-15] >>> 3);
                    var s1 = rotr(W[t-2],17) ^ rotr(W[t-2],19)  ^ (W[t-2]  >>> 10);
                    W[t] = add(add(W[t-16], s0), add(W[t-7], s1));
                }
                var a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
                for (var t = 0; t < 64; t++) {
                    var T1 = add(add(add(h, rotr(e,6)^rotr(e,11)^rotr(e,25)),
                                     add((e&f)^(~e&g), K[t])), W[t]);
                    var T2 = add(rotr(a,2)^rotr(a,13)^rotr(a,22), (a&b)^(a&c)^(b&c));
                    h=g; g=f; f=e; e=add(d,T1); d=c; c=b; b=a; a=add(T1,T2);
                }
                H[0]=add(H[0],a); H[1]=add(H[1],b); H[2]=add(H[2],c); H[3]=add(H[3],d);
                H[4]=add(H[4],e); H[5]=add(H[5],f); H[6]=add(H[6],g); H[7]=add(H[7],h);
            }
            return H;
        }

        function strToBytes(s) {
            var b = [];
            for (var i = 0; i < s.length; i++) {
                var c = s.charCodeAt(i);
                if (c < 0x80) { b.push(c); }
                else if (c < 0x800) { b.push(0xc0|(c>>6)); b.push(0x80|(c&0x3f)); }
                else { b.push(0xe0|(c>>12)); b.push(0x80|((c>>6)&0x3f)); b.push(0x80|(c&0x3f)); }
            }
            return b;
        }

        function wordsToBytes(w) {
            var b = [];
            for (var i = 0; i < w.length; i++) {
                b.push((w[i]>>>24)&0xff); b.push((w[i]>>>16)&0xff);
                b.push((w[i]>>>8) &0xff); b.push(w[i]&0xff);
            }
            return b;
        }

        function wordsToHex(w) {
            var h = '';
            for (var i = 0; i < w.length; i++) h += ('00000000'+(w[i]>>>0).toString(16)).slice(-8);
            return h;
        }

        var bsize = 64;
        var kb = strToBytes(key);
        if (kb.length > bsize) kb = wordsToBytes(sha256(kb));
        while (kb.length < bsize) kb.push(0);

        var ik = [], ok = [];
        for (var i = 0; i < bsize; i++) { ik.push(kb[i]^0x36); ok.push(kb[i]^0x5c); }

        var inner = wordsToBytes(sha256(ik.concat(strToBytes(message))));
        return wordsToHex(sha256(ok.concat(inner)));
    },

    type: 'XurrentHMACUtil'
};
